#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum PlaybackState {
    Hidden,
    Preparing,
    Playing,
    Paused,
    AwaitingRoute,
    Finished,
    Message,
}

impl PlaybackState {
    const fn id(self) -> &'static str {
        match self {
            Self::Hidden => "hidden",
            Self::Preparing => "preparing",
            Self::Playing => "playing",
            Self::Paused => "paused",
            Self::AwaitingRoute => "awaitingRoute",
            Self::Finished => "finished",
            Self::Message => "message",
        }
    }
}

struct CloudSegment {
    audio: TempPath,
    duration_ms: u64,
    word_timings: Vec<google::WordTiming>,
}

#[derive(Serialize)]
#[serde(rename_all = "camelCase")]
struct Snapshot<'a> {
    settings: &'a Settings,
    supported_languages: &'static [(&'static str, &'static str)],
    system_voices: &'a [SystemVoice],
    azure_voices: &'a [AzureVoice],
    google_voices: &'a [GoogleVoice],
}

