impl FlowBackend {
    fn start_services(&mut self) {
        if self.services_started {
            return;
        }
        self.services_started = true;

        let (sender, receiver) = mpsc::unbounded_channel();
        self.shortcut_commands = Some(sender);
        let activation_pointer = QPointer::from(&*self);
        let activated = queued_callback(move |()| {
            if let Some(backend) = activation_pointer.as_pinned() {
                backend.borrow_mut().request_selection();
            }
        });
        let status_pointer = QPointer::from(&*self);
        let status = queued_callback(move |message: String| {
            if let Some(backend) = status_pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                backend.shortcut_status = message.into();
                backend.shortcut_status_changed();
            }
        });
        let preset = self.settings.hot_key;
        std::thread::spawn(move || {
            let runtime = tokio::runtime::Runtime::new().expect("Flow can create an async runtime");
            runtime.block_on(shortcuts::run(
                preset,
                receiver,
                shortcuts::Callbacks { activated, status },
            ));
        });

        let voices_pointer = QPointer::from(&*self);
        let voices_changed = queued_callback(move |voices: Vec<SystemVoice>| {
            if let Some(backend) = voices_pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                backend.system_voices = voices;
                backend.refresh_snapshot();
            }
        });
        let finished_pointer = QPointer::from(&*self);
        let finished_generation = Arc::clone(&self.playback_generation);
        let finished = queued_callback(move |generation: u64| {
            if finished_generation.load(Ordering::SeqCst) != generation {
                return;
            }
            if let Some(backend) = finished_pointer.as_pinned() {
                backend.borrow_mut().finish_reading();
            }
        });
        let failed_pointer = QPointer::from(&*self);
        let failed_generation = Arc::clone(&self.playback_generation);
        let failed = queued_callback(move |(generation, message): (u64, String)| {
            if failed_generation.load(Ordering::SeqCst) != generation {
                return;
            }
            if let Some(backend) = failed_pointer.as_pinned() {
                backend.borrow_mut().show_message(message);
            }
        });
        self.system_speech_commands = Some(system_speech::start(system_speech::Callbacks {
            voices_changed: Box::new(voices_changed),
            finished: Box::new(finished),
            failed: Box::new(failed),
        }));

        if self.settings.azure_endpoint.is_some() {
            self.load_azure_voices();
        }
        if self.settings.google_api_key_configured {
            self.load_google_voices();
        }
    }

    fn request_selection(&mut self) {
        let request_id = self.selection_generation.fetch_add(1, Ordering::SeqCst) + 1;
        if selection::debug_enabled() {
            eprintln!("[Flow selection] request {request_id} received");
        }
        let generation = Arc::clone(&self.selection_generation);
        let pointer = QPointer::from(&*self);
        let deliver = queued_callback(move |result: Result<String, String>| {
            if generation.load(Ordering::SeqCst) != request_id {
                return;
            }
            if let Some(backend) = pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                match result {
                    Ok(text) => backend.handle_selection(text),
                    Err(message) => backend.show_message(message),
                }
            }
        });
        std::thread::spawn(move || {
            let runtime = tokio::runtime::Runtime::new().expect("Flow can create an async runtime");
            let result = runtime
                .block_on(selection::read_focused_selection())
                .map_err(|error| error.to_string());
            if selection::debug_enabled() {
                match &result {
                    Ok(text) => eprintln!(
                        "[Flow selection] request {request_id} resolved ({} characters)",
                        text.chars().count()
                    ),
                    Err(error) => {
                        eprintln!("[Flow selection] request {request_id} failed: {error}")
                    }
                }
            }
            deliver(result);
        });
    }

    fn handle_selection(&mut self, text: String) {
        // The override lasts until the next capture only.
        let had_language_override = self.text_language_override.is_some();
        self.text_language_override = None;
        self.text_language_override_changed();
        self.refresh_override_needs_route();

        let normalized = normalize(&text);
        if normalized.is_empty() {
            self.show_message(format!(
                "Select some text, then press {}.",
                self.settings.hot_key.title()
            ));
            return;
        }
        if normalized.chars().count() > MAXIMUM_SELECTION_CHARACTERS {
            self.show_message("This selection is longer than Flow's 10-minute reading limit.");
            return;
        }
        if normalized == normalize(&self.selected_text)
            && self.settings.same_selection_action == SameSelectionAction::PauseResume
            && matches!(
                self.playback_state,
                PlaybackState::Playing | PlaybackState::Paused
            )
            && !had_language_override
        {
            self.toggle_pause();
            return;
        }

        // Resetting an override requires a new Auto plan, so replay this
        // selection instead of resuming the old overridden plan.
        let plan = language::plan(&text, &self.settings);
        self.start_auto_plan(text, plan);
    }

    fn start_auto_plan(&mut self, text: String, plan: Plan) {
        if !plan.needs_language_check() {
            self.manual_route_needed = false;
            self.manual_route_needed_changed();
            self.start_plan(text, plan);
            return;
        }
        self.cancel_dismiss();
        self.stop_active_playback();
        self.selected_text = text;
        self.playback_text = playback_text(&plan, &text).into();
        self.playback_text_changed();
        self.plan = Some(plan);
        self.manual_route_needed = true;
        self.manual_route_needed_changed();
        self.refresh_detected_languages();
        self.set_state(PlaybackState::AwaitingRoute);
        self.set_popup_visible(true);
    }

    fn refresh_detected_languages(&mut self) {
        let mut tags: Vec<String> = Vec::new();
        if let Some(plan) = &self.plan {
            for sentence in &plan.sentences {
                if let Some(tag) = &sentence.detected_language_tag {
                    if !tags.contains(tag) {
                        tags.push(tag.clone());
                    }
                }
            }
        }
        self.detected_languages_json =
            serde_json::to_string(&tags).unwrap_or_else(|_| "[]".into()).into();
        self.detected_languages_json_changed();
        self.manual_route_sentence_text = self
            .plan
            .as_ref()
            .and_then(|plan| plan.sentences.iter().find(|sentence| sentence.needs_review))
            .map(|sentence| sentence.text.clone())
            .unwrap_or_default()
            .into();
        self.manual_route_sentence_text_changed();
    }

    fn refresh_override_needs_route(&mut self) {
        let unrouted = self
            .text_language_override
            .as_deref()
            .is_some_and(|tag| self.settings.language_route(tag).is_none());
        if self.override_needs_route != unrouted {
            self.override_needs_route = unrouted;
            self.override_needs_route_changed();
        }
    }

    fn start_plan(&mut self, text: String, plan: Plan) {
        self.cancel_dismiss();
        self.stop_active_playback();
        if self.manual_route_needed {
            self.manual_route_needed = false;
            self.manual_route_needed_changed();
        }
        self.selected_text = text;
        self.playback_text = playback_text(&plan, &text).into();
        self.playback_text_changed();
        self.plan = Some(plan.clone());
        self.refresh_detected_languages();
        self.set_state(PlaybackState::Preparing);
        self.set_popup_visible(true);
        let generation = self.playback_generation.fetch_add(1, Ordering::SeqCst) + 1;

        match self.settings.speech_source {
            SpeechSource::System => {
                self.set_state(PlaybackState::Playing);
                let sent = self.system_speech_commands.as_ref().is_some_and(|sender| {
                    sender
                        .send(system_speech::Command::Play { generation, plan })
                        .is_ok()
                });
                if !sent {
                    self.show_message("Flow could not start the system speech service.");
                }
            }
            SpeechSource::Azure => self.synthesize_azure(plan, generation),
            SpeechSource::Google => self.synthesize_google(plan, generation),
        }
    }

    fn synthesize_azure(&mut self, plan: Plan, generation: u64) {
        let Some(endpoint) = self.settings.azure_endpoint.clone() else {
            self.show_message("Set up Azure Speech before choosing Azure voice.");
            return;
        };
        let settings = self.settings.clone();
        let current_generation = Arc::clone(&self.playback_generation);
        let pointer = QPointer::from(&*self);
        let deliver = queued_callback(move |result: Result<Vec<(Vec<u8>, Vec<google::WordTiming>)>, String>| {
            if current_generation.load(Ordering::SeqCst) != generation {
                return;
            }
            if let Some(backend) = pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                match result {
                    Ok(audio) => backend.play_cloud_audio(audio, 160_000),
                    Err(message) => backend.show_message(message),
                }
            }
        });
        std::thread::spawn(move || {
            let result = azure::load_key()
                .and_then(|key| azure::synthesize(&endpoint, &key, &plan, &settings))
                .map(|audio| vec![(audio, Vec::new())])
                .map_err(|_| {
                    "Azure could not synthesize this selection. Check the endpoint, key, and voice."
                        .to_owned()
                });
            deliver(result);
        });
    }

    fn synthesize_google(&mut self, plan: Plan, generation: u64) {
        if !self.settings.google_api_key_configured {
            self.show_message("Set up Google Cloud Text-to-Speech before choosing Google voice.");
            return;
        }
        let current_generation = Arc::clone(&self.playback_generation);
        let settings = self.settings.clone();
        let pointer = QPointer::from(&*self);
        let deliver = queued_callback(move |result: Result<Vec<(Vec<u8>, Vec<google::WordTiming>)>, String>| {
            if current_generation.load(Ordering::SeqCst) != generation {
                return;
            }
            if let Some(backend) = pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                match result {
                    Ok(audio) => backend.play_cloud_audio(audio, 32_000),
                    Err(message) => backend.show_message(message),
                }
            }
        });
        std::thread::spawn(move || {
            let result = google::load_key()
                .and_then(|key| google::synthesize(&key, &plan, settings.word_highlighting_enabled))
                .map(|segments| segments.into_iter().map(|segment| (segment.audio, segment.word_timings)).collect())
                .map_err(|_| {
                    "Google Cloud could not synthesize this selection. Check the API key and voice."
                        .to_owned()
                });
            deliver(result);
        });
    }

    fn play_cloud_audio(&mut self, audio_segments: Vec<(Vec<u8>, Vec<google::WordTiming>)>, bits_per_second: u64) {
        let segments = audio_segments
            .into_iter()
            .map(|(audio, word_timings)| {
                tempfile::Builder::new()
                    .prefix("flow-")
                    .suffix(".mp3")
                    .tempfile()
                    .and_then(|mut file| {
                        file.write_all(&audio)?;
                        let duration_ms = (audio.len() as u64)
                            .saturating_mul(8_000)
                            .checked_div(bits_per_second.max(1))
                            .unwrap_or(0);
                        Ok(CloudSegment {
                            audio: file.into_temp_path(),
                            duration_ms,
                            word_timings,
                        })
                    })
            })
            .collect::<Result<Vec<_>, _>>();
        match segments {
            Ok(segments) if !segments.is_empty() => {
                self.cloud_segments = segments;
                self.cloud_current_segment = 0;
                if !self.playback_seek_supported {
                    self.playback_seek_supported = true;
                    self.playback_seek_supported_changed();
                }
                self.start_cloud_segment(0, 0);
            }
            _ => self
                .show_message("The cloud speech service returned audio that Flow could not play."),
        }
    }

    fn start_cloud_segment(&mut self, index: usize, offset_ms: i64) {
        let Some(segment) = self.cloud_segments.get(index) else {
            self.finish_reading();
            return;
        };
        self.cloud_current_segment = index;
        let url = format!("file://{}", segment.audio.display());
        let timings_json = serde_json::to_string(&segment.word_timings).unwrap_or_else(|_| "[]".into());
        self.set_state(PlaybackState::Playing);
        self.play_cloud(url.into(), timings_json.into(), offset_ms);
    }

    fn cloud_segment_finished(&mut self) {
        if !matches!(
            self.playback_state,
            PlaybackState::Playing | PlaybackState::Paused
        ) {
            return;
        }
        self.start_cloud_segment(self.cloud_current_segment + 1, 0);
    }

    fn seek_cloud(&mut self, fraction: f64) {
        if !self.playback_seek_supported || self.cloud_segments.is_empty() {
            return;
        }
        let total_ms: u64 = self.cloud_segments.iter().map(|s| s.duration_ms).sum();
        if total_ms == 0 {
            return;
        }
        let clamped = fraction.clamp(0.0, 1.0);
        let mut remaining = (clamped * total_ms as f64).round() as i64;
        for (index, segment) in self.cloud_segments.iter().enumerate() {
            let duration = segment.duration_ms as i64;
            if remaining > duration && index < self.cloud_segments.len() - 1 {
                remaining -= duration;
                continue;
            }
            let within = remaining.clamp(0, duration);
            if index == self.cloud_current_segment {
                self.seek_audio(within);
                self.update_cloud_progress(within.max(0) as u64);
            } else {
                let was_paused = self.playback_state == PlaybackState::Paused;
                self.start_cloud_segment(index, within);
                if was_paused {
                    self.pause_playback();
                }
            }
            return;
        }
    }

    fn update_cloud_progress(&mut self, position_in_current_ms: u64) {
        let Some(current_duration) = self
            .cloud_segments
            .get(self.cloud_current_segment)
            .map(|segment| segment.duration_ms)
        else {
            return;
        };
        let total_ms: u64 = self.cloud_segments.iter().map(|s| s.duration_ms).sum();
        if total_ms == 0 {
            return;
        }
        let elapsed_before: u64 = self
            .cloud_segments
            .iter()
            .take(self.cloud_current_segment)
            .map(|segment| segment.duration_ms)
            .sum();
        let elapsed =
            elapsed_before + position_in_current_ms.min(current_duration);
        let progress = ((elapsed as f64 / total_ms as f64).clamp(0.0, 1.0) * 1000.0).round() / 1000.0;
        if (progress - self.playback_progress).abs() >= 0.001 {
            self.playback_progress = progress;
            self.playback_progress_changed();
        }
    }

    fn reset_cloud_timeline(&mut self) {
        self.cloud_segments.clear();
        self.cloud_current_segment = 0;
        if self.playback_seek_supported {
            self.playback_seek_supported = false;
            self.playback_seek_supported_changed();
        }
        if self.playback_progress != 0.0 {
            self.playback_progress = 0.0;
            self.playback_progress_changed();
        }
    }

    fn toggle_pause(&mut self) {
        match self.playback_state {
            PlaybackState::Playing => {
                if let Some(sender) = &self.system_speech_commands {
                    let _ = sender.send(system_speech::Command::Pause);
                }
                self.pause_playback();
                self.set_state(PlaybackState::Paused);
            }
            PlaybackState::Paused => {
                if let Some(sender) = &self.system_speech_commands {
                    let _ = sender.send(system_speech::Command::Resume);
                }
                self.resume_playback();
                self.set_state(PlaybackState::Playing);
            }
            _ => {}
        }
    }

    fn stop_reading(&mut self) {
        self.cancel_dismiss();
        self.stop_active_playback();
        self.selected_text.clear();
        self.plan = None;
        self.refresh_detected_languages();
        self.set_state(PlaybackState::Hidden);
        self.set_popup_visible(false);
    }

    fn stop_active_playback(&mut self) {
        self.playback_generation.fetch_add(1, Ordering::SeqCst);
        if let Some(sender) = &self.system_speech_commands {
            let _ = sender.send(system_speech::Command::Stop);
        }
        self.stop_audio();
        self.reset_cloud_timeline();
    }

    fn finish_reading(&mut self) {
        if !matches!(
            self.playback_state,
            PlaybackState::Playing | PlaybackState::Paused
        ) {
            return;
        }
        self.reset_cloud_timeline();
        self.set_state(PlaybackState::Finished);
        self.dismiss_after_delay();
    }

    fn show_message(&mut self, message: impl Into<String>) {
        self.cancel_dismiss();
        self.stop_active_playback();
        self.selected_text.clear();
        self.plan = None;
        self.refresh_detected_languages();
        self.message = message.into().into();
        self.message_changed();
        self.set_state(PlaybackState::Message);
        self.set_popup_visible(true);
        self.dismiss_after_delay();
    }

    fn dismiss_after_delay(&mut self) {
        let request_id = self.dismiss_generation.fetch_add(1, Ordering::SeqCst) + 1;
        let generation = Arc::clone(&self.dismiss_generation);
        let delay = self.settings.popup_dismiss_seconds.clamp(3.0, 30.0);
        let pointer = QPointer::from(&*self);
        let dismiss = queued_callback(move |()| {
            if generation.load(Ordering::SeqCst) != request_id {
                return;
            }
            if let Some(backend) = pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                backend.selected_text.clear();
                backend.plan = None;
                backend.set_state(PlaybackState::Hidden);
                backend.set_popup_visible(false);
            }
        });
        std::thread::spawn(move || {
            std::thread::sleep(Duration::from_secs_f64(delay));
            dismiss(());
        });
    }

    fn cancel_dismiss(&self) {
        self.dismiss_generation.fetch_add(1, Ordering::SeqCst);
    }

    fn add_language_route(&mut self, language_tag: &str) {
        let supported = language::supported_languages()
            .iter()
            .any(|(tag, _)| tag.eq_ignore_ascii_case(language_tag));
        let duplicate = self
            .settings
            .all_language_routes()
            .iter()
            .any(|route| language_base(&route.language_tag) == language_base(language_tag));
        if supported && !duplicate {
            let mut route = LanguageRoute::new(language_tag);
            route.system_voice_name = self
                .system_voices
                .iter()
                .find(|voice| language_base(&voice.language_tag) == language_base(language_tag))
                .map(|voice| voice.name.clone());
            route.azure_voice_name = self
                .azure_voices
                .iter()
                .find(|voice| {
                    language_base(&voice.locale) == language_base(language_tag)
                        || voice
                            .secondary_locales
                            .iter()
                            .any(|locale| language_base(locale) == language_base(language_tag))
                })
                .map(|voice| voice.short_name.clone())
                .or_else(|| Some(self.settings.azure_voice_name.clone()));
            route.google_voice_name = self
                .google_voices
                .iter()
                .find(|voice| {
                    voice
                        .language_codes
                        .iter()
                        .any(|locale| language_base(locale) == language_base(language_tag))
                })
                .map(|voice| voice.name.clone());
            route.azure_speech_rate = self.settings.azure_speech_rate;
            route.google_speech_rate = self.settings.google_speech_rate;
            self.settings.language_routes.push(route);
            self.persist_settings();
        }
    }

    fn apply_setting(&mut self, key: &str, value: &str) {
        let previous_hotkey = self.settings.hot_key;
        match key {
            "speechSource" => {
                self.settings.speech_source = match value {
                    "azure" => SpeechSource::Azure,
                    "google" => SpeechSource::Google,
                    _ => SpeechSource::System,
                };
                self.configuration_error = QString::default();
                self.configuration_error_changed();
            }
            "hotKey" => {
                self.settings.hot_key = match value {
                    "altSuperSpace" => HotKeyPreset::AltSuperSpace,
                    "controlAltR" => HotKeyPreset::ControlAltR,
                    _ => HotKeyPreset::AltSuperR,
                };
            }
            "systemVoiceName" => {
                self.settings.system_voice_name = nonempty(value);
            }
            "systemSpeechRate" => {
                if let Ok(rate) = value.parse::<f64>() {
                    self.settings.system_speech_rate = rate.clamp(-1.0, 1.0);
                }
            }
            "popupDismissSeconds" => {
                if let Ok(seconds) = value.parse::<f64>() {
                    self.settings.popup_dismiss_seconds = seconds.clamp(3.0, 30.0);
                }
            }
            "sameSelectionAction" => {
                self.settings.same_selection_action = if value == "restart" {
                    SameSelectionAction::Restart
                } else {
                    SameSelectionAction::PauseResume
                };
            }
            "wordHighlightingEnabled" => self.settings.word_highlighting_enabled = value == "true",
            "azureVoiceName" => self.settings.azure_voice_name = value.into(),
            "azureSpeechRate" => {
                if let Ok(rate) = value.parse::<f64>() {
                    self.settings.azure_speech_rate = rate.clamp(-1.0, 1.0);
                }
            }
            "azureVoiceMode" => {
                self.settings.azure_voice_mode = if value == "perLanguage" {
                    AzureVoiceMode::PerLanguage
                } else {
                    AzureVoiceMode::Multilingual
                };
            }
            "googleVoiceName" => self.settings.google_voice_name = nonempty(value),
            "googleSpeechRate" => {
                if let Ok(rate) = value.parse::<f64>() {
                    self.settings.google_speech_rate = rate.clamp(-1.0, 1.0);
                }
            }
            "defaultLanguageTag" => {
                self.settings.default_language_tag = value.into();
                self.settings.google_voice_name = None;
            }
            "languageSwitchingEnabled" => {
                self.settings.language_switching_enabled = value == "true"
            }
            _ => return,
        }
        if previous_hotkey != self.settings.hot_key
            && let Some(sender) = &self.shortcut_commands
        {
            let _ = sender.send(shortcuts::Command::Change(self.settings.hot_key));
        }
        self.persist_settings();
    }

    fn apply_route_setting(&mut self, route_id: &str, field: &str, value: &str) {
        let Ok(id) = Uuid::parse_str(route_id) else {
            return;
        };
        if id == DEFAULT_LANGUAGE_ROUTE_ID {
            match field {
                "systemVoiceName" => self.settings.system_voice_name = nonempty(value),
                "systemSpeechRate" => {
                    if let Ok(rate) = value.parse::<f64>() {
                        self.settings.system_speech_rate = rate.clamp(-1.0, 1.0);
                    }
                }
                "azureVoiceName" => self.settings.azure_voice_name = value.into(),
                "azureSpeechRate" => {
                    if let Ok(rate) = value.parse::<f64>() {
                        self.settings.azure_speech_rate = rate.clamp(-1.0, 1.0);
                    }
                }
                "googleVoiceName" => self.settings.google_voice_name = nonempty(value),
                "googleSpeechRate" => {
                    if let Ok(rate) = value.parse::<f64>() {
                        self.settings.google_speech_rate = rate.clamp(-1.0, 1.0);
                    }
                }
                _ => return,
            }
        } else if let Some(route) = self
            .settings
            .language_routes
            .iter_mut()
            .find(|r| r.id == id)
        {
            match field {
                "systemVoiceName" => route.system_voice_name = nonempty(value),
                "systemSpeechRate" => {
                    if let Ok(rate) = value.parse::<f64>() {
                        route.system_speech_rate = rate.clamp(-1.0, 1.0);
                    }
                }
                "azureVoiceName" => route.azure_voice_name = nonempty(value),
                "azureSpeechRate" => {
                    if let Ok(rate) = value.parse::<f64>() {
                        route.azure_speech_rate = rate.clamp(-1.0, 1.0);
                    }
                }
                "googleVoiceName" => route.google_voice_name = nonempty(value),
                "googleSpeechRate" => {
                    if let Ok(rate) = value.parse::<f64>() {
                        route.google_speech_rate = rate.clamp(-1.0, 1.0);
                    }
                }
                _ => return,
            }
        } else {
            return;
        }
        self.persist_settings();
    }

    fn save_azure(&mut self, raw_endpoint: &str, raw_key: &str) {
        let result = azure::normalize_endpoint(raw_endpoint)
            .and_then(|endpoint| azure::validate_key(raw_key).map(|key| (endpoint, key)))
            .and_then(|(endpoint, key)| {
                azure::save_key(&key)?;
                Ok(endpoint)
            });
        match result {
            Ok(endpoint) => {
                self.settings.azure_endpoint = Some(endpoint);
                self.configuration_error = QString::default();
                self.configuration_error_changed();
                self.persist_settings();
                self.load_azure_voices();
            }
            Err(error) => {
                self.configuration_error = error.to_string().into();
                self.configuration_error_changed();
            }
        }
    }

    fn load_azure_voices(&mut self) {
        let Some(endpoint) = self.settings.azure_endpoint.clone() else {
            return;
        };
        self.configuration_error = QString::default();
        self.configuration_error_changed();
        let pointer = QPointer::from(&*self);
        let deliver = queued_callback(move |result: Result<Vec<AzureVoice>, String>| {
            if let Some(backend) = pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                match result {
                    Ok(voices) => {
                        backend.azure_voices = voices;
                        backend.configuration_error = QString::default();
                        backend.configuration_error_changed();
                        backend.refresh_snapshot();
                    }
                    Err(message) => {
                        backend.configuration_error = message.into();
                        backend.configuration_error_changed();
                    }
                }
            }
        });
        std::thread::spawn(move || {
            let result = azure::load_key()
                .and_then(|key| azure::list_voices(&endpoint, &key))
                .map_err(|_| {
                    "Flow could not load Azure voices. Check the endpoint and key.".to_owned()
                });
            deliver(result);
        });
    }

    fn save_google(&mut self, raw_key: &str) {
        let result = google::validate_key(raw_key).and_then(|key| google::save_key(&key));
        match result {
            Ok(()) => {
                self.settings.google_api_key_configured = true;
                self.configuration_error = QString::default();
                self.configuration_error_changed();
                self.persist_settings();
                self.load_google_voices();
            }
            Err(error) => {
                self.configuration_error = error.to_string().into();
                self.configuration_error_changed();
            }
        }
    }

    fn load_google_voices(&mut self) {
        if !self.settings.google_api_key_configured {
            return;
        }
        self.configuration_error = QString::default();
        self.configuration_error_changed();
        let pointer = QPointer::from(&*self);
        let deliver = queued_callback(move |result: Result<Vec<GoogleVoice>, String>| {
            if let Some(backend) = pointer.as_pinned() {
                let mut backend = backend.borrow_mut();
                match result {
                    Ok(voices) => {
                        backend.google_voices = voices;
                        backend.configuration_error = QString::default();
                        backend.configuration_error_changed();
                        backend.refresh_snapshot();
                    }
                    Err(message) => {
                        backend.configuration_error = message.into();
                        backend.configuration_error_changed();
                    }
                }
            }
        });
        std::thread::spawn(move || {
            let result = google::load_key()
                .and_then(|key| google::list_voices(&key))
                .map_err(|_| {
                    "Flow could not load Google voices. Check the API key and confirm that Cloud Text-to-Speech is enabled."
                        .to_owned()
                });
            deliver(result);
        });
    }

    fn persist_settings(&mut self) {
        if settings::save(&self.settings).is_err() {
            self.configuration_error = "Flow could not save its settings.".into();
            self.configuration_error_changed();
        }
        self.refresh_snapshot();
    }

    fn refresh_snapshot(&mut self) {
        self.snapshot_json = serialize(&Snapshot {
            settings: &self.settings,
            supported_languages: language::supported_languages(),
            system_voices: &self.system_voices,
            azure_voices: &self.azure_voices,
            google_voices: &self.google_voices,
        })
        .into();
        self.snapshot_json_changed();
    }

    fn set_state(&mut self, state: PlaybackState) {
        if self.playback_state == state {
            return;
        }
        self.playback_state = state;
        self.state = state.id().into();
        self.state_changed();
    }

    fn set_popup_visible(&mut self, visible: bool) {
        if self.popup_visible == visible {
            return;
        }
        self.popup_visible = visible;
        self.popup_visible_changed();
    }
}

impl Drop for FlowBackend {
    fn drop(&mut self) {
        if let Some(sender) = &self.shortcut_commands {
            let _ = sender.send(shortcuts::Command::Stop);
        }
        if let Some(sender) = &self.system_speech_commands {
            let _ = sender.send(system_speech::Command::Shutdown);
        }
    }
}

fn normalize(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

/// Retains source paragraph breaks without changing the one-code-unit sentence
/// separators used by the Google word-boundary offsets.
fn playback_text(plan: &Plan, source: &str) -> String {
    if plan.sentences.len() < 2 {
        return plan
            .sentences
            .first()
            .map_or_else(|| source.into(), |sentence| sentence.text.clone());
    }

    let mut ranges = Vec::with_capacity(plan.sentences.len());
    let mut search_start = 0;
    for sentence in &plan.sentences {
        let Some(offset) = source[search_start..].find(&sentence.text) else {
            return plan
                .sentences
                .iter()
                .map(|sentence| sentence.text.as_str())
                .collect::<Vec<_>>()
                .join(" ");
        };
        let start = search_start + offset;
        let end = start + sentence.text.len();
        ranges.push(start..end);
        search_start = end;
    }

    let mut text = String::new();
    for (index, sentence) in plan.sentences.iter().enumerate() {
        text.push_str(&sentence.text);
        if index + 1 < plan.sentences.len() {
            let gap = &source[ranges[index].end..ranges[index + 1].start];
            text.push(if gap.matches('\n').count() >= 2 {
                '\n'
            } else {
                ' '
            });
        }
    }
    text
}

fn nonempty(value: &str) -> Option<String> {
    let trimmed = value.trim();
    (!trimmed.is_empty()).then(|| trimmed.to_owned())
}

fn serialize<T: Serialize>(value: &T) -> String {
    serde_json::to_string(value).unwrap_or_else(|_| "null".into())
}
